import subprocess

def verbosity(args):
    p=subprocess.run(["./executable"]+args+["--echo"], capture_output=True, text=True)
    has_pfring="pfring" in p.stderr
    # Count verbosity level by pfring presence (level>=2) vs detailed pcap (level>=1) vs basic (level0)
    if has_pfring:
        return 2
    elif "pcap_close" in p.stderr:
        return 1
    elif "failed to load libpcap" in p.stderr:
        return 0
    else:
        return -1

for args in [["-v"],["-vv"],["-vvv"],["-d"],["-dd"],["-vd"],["-dv"],["-vdd"],["-dvv"],["-vvd"],["-ddv"],["-v2"],["-d2"],["-vv2"],["-dd2"],["-v","-d"],["-d","-v"],["-v","-v"],["-d","-d"]]:
    print(f"{args} => {verbosity(args)}")

