import subprocess, re

def get_ports_set(n):
    p=subprocess.run(["./executable","--seed","123","--top-ports",str(n),"--echo"], capture_output=True, text=True)
    for line in p.stdout.splitlines():
        if line.startswith("ports ="):
            s=line.split("=",1)[1].strip()
            if s=="":
                return set()
            # parse ranges into set
            res=set()
            for part in s.split(","):
                if "-" in part:
                    a,b=part.split("-")
                    for port in range(int(a),int(b)+1):
                        res.add(port)
                else:
                    if part:
                        res.add(int(part))
            return res
    return None

# Build ordered list by incremental
prev=get_ports_set(2)
print("2:",sorted(prev))
ordered=[80,443]  # assume order? Need to determine: for N=2, which is first? Could be 80 then 443 (likely). We'll assume 80,443.
