for n in range(3,50):
    cur=get_ports_set(n)
    diff=cur-prev
    if len(diff)!=1:
        print(f"n={n} diff size {len(diff)} diff={sorted(diff)} prev={sorted(prev)} cur={sorted(cur)}")
    else:
        print(f"n={n} adds {list(diff)[0]}")
    prev=cur

