import subprocess, json

def get_ports_str(n):
    p=subprocess.run(["./executable","--seed","123","--top-ports",str(n),"--echo"], capture_output=True, text=True)
    for line in p.stdout.splitlines():
        if line.startswith("ports ="):
            return line.split("=",1)[1].strip()
    return None

# Capture for n=0..1100, but only store when changes? Actually need for each n, but to save space, store ordered unique list + mapping from n to unique count?
# Let's capture ordered unique additions: for each n, diff from prev (if diff size 1, record added port; if diff 0, record None for duplicate)

prev=set()
ordered_unique=[]
n_to_unique_count={}
# Also need to handle n=0,1 special
for n in range(0,1101):
    s=get_ports_str(n)
    # parse to set
    cur=set()
    if s:
        for part in s.split(","):
            if "-" in part:
                a,b=part.split("-")
                for port in range(int(a),int(b)+1):
                    cur.add(port)
            else:
                cur.add(int(part))
    if n==0:
        assert len(cur)==0
    elif n==1:
        # should be 20 ports (same as 20)
        pass
    else:
        # for n>=2, cur should be superset of prev (or equal if duplicate)
        if not cur.issuperset(prev):
            print(f"n={n} not superset! prev {len(prev)} cur {len(cur)}")
        diff=cur-prev
        if len(diff)==1:
            ordered_unique.append(list(diff)[0])
        elif len(diff)==0:
            ordered_unique.append(None)  # duplicate, unknown which port duplicated
        else:
            print(f"n={n} diff {len(diff)}")
    n_to_unique_count[n]=len(cur)
    prev=cur
    if n%100==0:
        print(f"n={n} unique={len(cur)}")

print(f"ordered_unique len {len(ordered_unique)}")
print(ordered_unique[:50])
# Save to file
open("/tmp/top_ports.json","w").write(json.dumps({"ordered_unique":ordered_unique, "n_to_unique_count":n_to_unique_count}))
