        if not port_set:
            return None
        sorted_ports=sorted(port_set)
        # Merge into ranges
        ranges=[]
        start=prev=sorted_ports[0]
        for p in sorted_ports[1:]:
            if p==prev+1:
                prev=p
            else:
                if start==prev:
                    ranges.append(str(start))
                else:
                    ranges.append(f"{start}-{prev}")
                start=prev=p
        if start==prev:
            ranges.append(str(start))
        else:
            ranges.append(f"{start}-{prev}")
        return ",".join(ranges)
